// Multithreaded TCP server
import java.net.*;import java.io.*;public class Q20 {public static void main(String[] args)throws Exception{try(ServerSocket server=new ServerSocket(5002)){System.out.println("MultiClientServer on 5002 (Ctrl+C to stop)");while(true){Socket client=server.accept();Thread worker=new Thread(()->{try(Socket socket=client;BufferedReader in=new BufferedReader(new InputStreamReader(socket.getInputStream()))){String msg=in.readLine();System.out.println(Thread.currentThread().getName()+": "+msg);}catch(IOException e){System.err.println("Client error: "+e.getMessage());}});worker.start();}}}}
